using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B4PolishRefine {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_LayoutPolish/";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};static Vector3 V(JToken v)=>new Vector3((float)v[0],(float)v[1],(float)v[2]);
 static bool Free(Vector3 p)=>!Physics.CheckCapsule(p+Vector3.up*.43f,p+Vector3.up*1.5f,.34f,~0,QueryTriggerInteraction.Ignore);
 public static object Fix(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();bool enabled=cc.enabled;cc.enabled=false;var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var records=new List<object>();
 var rack=ts.Single(t=>t.name=="B4_C04_ReturnRack_014");rack.gameObject.SetActive(false);PrefabUtility.RecordPrefabInstancePropertyModifications(rack.gameObject);foreach(var w in plan["workspaces"].Where(w=>(string)w["name"]==rack.name).ToArray())w.Remove();
 var bench=ts.Single(t=>t.name=="B4_C04_AnalysisBench_02");bench.position=new Vector3(24.46f,-66,-18.2f)+bench.forward*1.15f;PrefabUtility.RecordPrefabInstancePropertyModifications(bench);var benchPlan=plan["placements"].Single(p=>(string)p["name"]==bench.name);benchPlan["position"]=JArray.FromObject(V(bench.position-new Vector3(26,-66,-13)));Physics.SyncTransforms();
 try{foreach(string name in new[]{"B4_C04_UtilityServiceSpine_07","B4_C04_WallSafety_003"}){var t=ts.Single(q=>q.name==name);var room=plan["rooms"].Single(r=>(string)r["id"]=="C04");Vector3 center=new Vector3(26,-66,-13);float rad=8;bool safety=name.Contains("WallSafety");var start=t.position;var rot=t.rotation;var mycols=t.GetComponentsInChildren<Collider>();foreach(var c in mycols)c.enabled=false;Physics.SyncTransforms();
 var candidates=new List<Tuple<float,Vector3,Quaternion,Vector3>>();float w=safety?1.34f:2.7f,d=safety?.44f:.54f,h=safety?2.1f:2.25f;float rho=safety?Mathf.Sqrt(rad*rad-2.13f*2.13f)-.20f:Mathf.Sqrt(rad*rad-h*h)-d*.5f-.30f;
 for(int a=0;a<360;a+=2){if(room["doors"].Any(door=>Mathf.Abs(Mathf.DeltaAngle(a,(float)door["angle"]))<Mathf.Asin((2.35f+w/2)/rad)*Mathf.Rad2Deg))continue;var q=Quaternion.Euler(0,270-a,0);var pos=center+new Vector3(Mathf.Cos(a*Mathf.Deg2Rad)*rho,0,Mathf.Sin(a*Mathf.Deg2Rad)*rho);var bp=pos+q*new Vector3(0,h*.5f,safety?.21f:0);if(Physics.OverlapBox(bp,new Vector3(w*.5f+.08f,h*.5f-.09f,d*.5f+.06f),q,~0,QueryTriggerInteraction.Ignore).Any(c=>c.transform.position.y>-68&&!c.name.Contains("Floor")))continue;var ap=pos+q*new Vector3(0,0,safety?1.15f:d/2+.65f);if(!Free(ap))continue;candidates.Add(Tuple.Create(Vector3.Distance(start,pos),pos,q,ap));}
 if(!safety){var op=new Vector3(1.9523359f,0,4.3850182f);var oq=Quaternion.Euler(0,204,0);candidates.Insert(0,Tuple.Create(-1f,center+op,oq,center+op+oq*new Vector3(0,0,1.0f)));}
 bool ok=false;Vector3 chosenAccess=default;foreach(var candidate in candidates.OrderBy(c=>c.Item1)){t.SetPositionAndRotation(candidate.Item2,candidate.Item3);foreach(var c in mycols)c.enabled=true;Physics.SyncTransforms();float step=.25f;int n=65;var valid=new bool[n*n];Vector3 Pos(int i)=>center+new Vector3(-8+i%n*step,0,-8+i/n*step);for(int i=0;i<valid.Length;i++)valid[i]=Vector3.Distance(Pos(i),center)<7.85f&&Free(Pos(i));int Nearest(Vector3 p)=>Enumerable.Range(0,n*n).Where(i=>valid[i]).OrderBy(i=>(Pos(i)-p).sqrMagnitude).First();var door=room["doors"][0];int begin=Nearest(center+new Vector3((float)door["x"],0,(float)door["z"]));var seen=new HashSet<int>{begin};var queue=new Queue<int>();queue.Enqueue(begin);while(queue.Count>0){int i=queue.Dequeue();foreach(int j in new[]{i-1,i+1,i-n,i+n})if(j>=0&&j<n*n&&Mathf.Abs(j%n-i%n)<=1&&valid[j]&&seen.Add(j))queue.Enqueue(j);}
 int target=Nearest(candidate.Item4);records.Add(new{candidate=V(candidate.Item2-center),valid=valid.Count(v=>v),connected=seen.Count,target=V(Pos(target)-center),reachable=seen.Contains(target),delta=Vector3.Distance(Pos(target),candidate.Item4)});if(seen.Contains(target)&&Vector3.Distance(Pos(target),candidate.Item4)<.45f){ok=true;chosenAccess=candidate.Item4;break;}foreach(var c in mycols)c.enabled=false;Physics.SyncTransforms();}
 if(!ok){t.SetPositionAndRotation(start,rot);foreach(var c in mycols)c.enabled=true;File.WriteAllText(H+"candidate_debug.json",JsonConvert.SerializeObject(records,Formatting.Indented));throw new Exception("No reachable position: "+name+" candidates="+candidates.Count);}PrefabUtility.RecordPrefabInstancePropertyModifications(t);var access=plan["workspaces"].Single(wr=>(string)wr["name"]==name);access["point"]=JArray.FromObject(V(chosenAccess-center));access["polygon"]?.Parent.Remove();foreach(var p in plan["newPlacements"].Where(p=>(string)p["name"]==name)){p["position"]=JArray.FromObject(V(t.position-center));p["yaw"]=t.eulerAngles.y;}records.Add(new{name,position=V(t.position-center),yaw=t.eulerAngles.y,access=V(chosenAccess-center)});
 }}finally{cc.enabled=enabled;Physics.SyncTransforms();}
 // Surface details are seated on the actual top, away from existing controls.
 foreach(var t in ts.Where(t=>t.name.Contains("_BenchDetail_"))){string asset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.parent.gameObject);Vector3 p=t.localPosition;if(asset.Contains("OperatorIsland"))p=new Vector3(0,.915f,-.40f);else if(asset.Contains("ProtocolTable"))p=new Vector3(-1.16f,.915f,-.45f);else if(asset.Contains("DualReviewStation"))p=new Vector3(-1.02f,.915f,.33f);else if(asset.Contains("ResearchDesk"))p=new Vector3(-.66f,.895f,.25f);else if(asset.Contains("AnalysisBench"))p=new Vector3(1.15f,.895f,.25f);else if(asset.Contains("SensorWorkbench"))p=new Vector3(-1.03f,.895f,.25f);else if(asset.Contains("ObservationBooth"))p=new Vector3(1.30f,.935f,-.55f);t.localPosition=p;t.localScale=Vector3.one*.72f;PrefabUtility.RecordPrefabInstancePropertyModifications(t);}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(H+"layout.json",plan.ToString());File.WriteAllText(H+"refinements.json",JsonConvert.SerializeObject(records,Formatting.Indented));return records;}
